x_comment(x_subTopicFnTakesSpecs,"(#$subTopicFnTakesSpecs SUBTOPFN COLL) means that, within the context in which this assertion is made, each specialization SPEC of COLL is a good, sensible argument for the SubTopicFunction SUBTOPFN. In other words, it would be reasonable to form the non-atomic term (SUBTOPFN SPEC) and to discuss the topic determined by that term.  For example, (#$subTopicFnTakesSpecs #$FanSiteFn #$Movie-CW) means that every specialization MOVIETYPE of #$Movie-CW is a good, sensible argument for #$FanSiteFn -- it is reasonable to talk about fan sites for that spec.  Note that this assertion does not mean that for every spec MOVIETYPE there is at least one such fan site.  It means only that it is reasonable and normal (within the context in which the assertion is made) to ask, assert, or otherwise reason about fan sites for MOVIETYPE (in contrast, say, to the abnormality of asking, asserting, or otherwise reasoning about the care and feeding of MOVIETYPE or instruction manuals for MOVIETYPE) .") :- x_cid(a65b1280033701).
xc_microtheory(a65b1280033701,x_WebSearchEnhancementMt).
xc_source_file(a65b1280033701,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/WebSearchEnhancementMt.krf').
