x_comment(x_subTopicFnTakesInstances,"(#$subTopicFnTakesInstances SUBTOPFN COLL) means that, within the context in which this assertion is made, each instance INST of COLL is a good, sensible argument for the SubTopicFunction SUBTOPFN. In other words, it would be reasonable to form the non-atomic term (SUBTOPFN INST) and to discuss the topic determined by that term.  For example, (#$subTopicFnTakesInstances #$FanSiteFn #$ActorInMovies) means that every instance ACTOR of #$ActorInMovies is a good, sensible argument for #$FanSiteFn -- it is reasonable to talk about fan sites for that instance.  Note that this assertion does not mean that for every instance ACTOR there is at least one such site. It means only that it is reasonable and normal (within the context in which the assertion is made) to ask, assert, or otherwise reason about fan sites for ACTOR (in contrast, say, to the abnormality of asking, asserting, or otherwise reasoning about maps of ACTOR or designs for building ACTOR) .") :- x_cid(a65b1280033706).
