x_comment(x_subTopicOrderedQueryWords,"(#$subTopicOrderedQueryWords SUBTOPIC LIST) means that LIST is an ordered sequence of query search terms that will be used to generate a web-search query for the subtopic SUBTOPIC in the context of a particular search concept. Terms that appear at the front of this list have greater value than those appearing further down the list. Should the list of search terms need to be pruned for a particular search, the order of this list will dictate which terms get pruned first (i.e., start at the back and work towards the front).") :- x_cid(a65b1280033710).
