x_comment(x_subTopicFnTakes,"(#$subTopicFnTakes SUBTOPFN THING) means that, within the context in which this assertion is made, THING is a good, sensible argument for the SubTopicFunction SUBTOPFN. In other words, it would be reasonable to form the non-atomic term (SUBTOPFN THING) and to discuss the topic determined by that term.  For example, (#$subTopicFnTakes #$FanSiteFn ElvisPresley) would mean that ElvisPresley is a good, sensible argument for #$FanSiteFn -- it is reasonable to talk about fan sites for Elvis.  Note that this assertion does not mean that there are in fact any such fan sites.  It means only that it is reasonable and normal (within the context in which the assertion is made) to ask, assert, or otherwise reason about fan sites for Elvis (in contrast, say, to the abnormality of asking, asserting, or otherwise reasoning about maps of Elvis or designs for building Elvis) .") :- x_cid(a65b1280033716).
