x_comment(x_qaFollowupsForbidden,"(#$qaFollowupsForbidden PRED X Y) means that #$qaFollowupConcepts will not be generated from X to Y for simple assertions using PRED. It is designed to be used in stating exceptions to rules that conclude (#$qaFollowupConcepts FORT FORMAT-STRING FOLLOWUP). For example, (#$qaFollowupsForbidden #$highestPointInRegion 1 2) would ensure           that a query on #$Oregon-State would not yield #$MountHood as a           followup, but would still allow #$Oregon-State as a followup for           #$MountHood. Note that this does not affect followups that are generated on           the basis of #$RuleMacroPredicates.") :- x_cid(a65b1280033723).
