x_comment(x_GameProgramTypeByHardware,"A collection of collections. Each instance of #$GameProgramTypeByHardware is a collection of games that can be played on a particular kind of computer system. For example, the collection of all games played on a #$SonyPlayStation-TheProduct, denoted by (#$GameForSystemFn #$SonyPlayStation-TheProduct) is an instance of #$GameProgramTypeByHardware.") :- x_cid(a65b1280033724).
