x_comment(x_qaConflateCompletely,"A way to say that two Cyc terms are too close in meaning for the distinction to matter for the purpose of web searching.  (#$qaConflateCompletely FORT1 FORT2) means that FORT1 and FORT2 should be treated as identical for the purpose of web searching.  In addition, neither fort should be 'preferred' over the other; searches related to FORT1 are just as plausible as searches related to FORT2.") :- x_cid(a65b1280033725).
