x_comment(x_subTopicFnException,"(#$subTopicFnException SUBTOPFN THING) means that THING is not a good argument to SubTopicFunction SUBTOPFN.  That is, it would not be normal or expected (in the context of this assertion) to ask, assert, or otherwise reason about the result of applying SUBTOPFN to THING.  This predicate is used to specify exceptions to assertions using #$subTopicFnTakesSpecs and #$subTopicFnTakesInstances (see also #$subTopicFnExceptionSpecs and #$subTopicFnExceptionInstances).") :- x_cid(a65b1280033727).
