x_comment(x_qaConflateTo,"A statement that two terms are too close in meaning for the distinction between them to matter to the Query Augmentation application. (qaConflateTo TERM1 TERM2) means that Query Augmentation should consider any lexical assertions on TERM1 as if they actually applied to TERM2.  This is in effect saying that the two terms are close enough in meaning that TERM1 should be treated exactly like TERM2 for the purpose of web searching.  A good example of this is the distinction between #$CalendarSummer and #$SummerSeason.  This is a distinction which is fine to have in the KB, but irrelevant for searching the World Wide Web.") :- x_cid(a65b128003372a).
