x_comment(x_mostNotableGenls,"If (#$mostNotableGenls COL1 COL2), then every instance of COL1 is an instance of COL2, and COL2 is the most important or most obvious collection that is a superset of COL1.  In other words, COL2 is what comes to mind as an answer to the question, ''What collection is COL1 a spec of?''.   For example, it's true that every #$Nose is a #$Protrusion, but the most important class of which it's a spec would be #$ExternalOrgan.") :- x_cid(a65b128003372f).
