x_comment(x_qaIrrelevantTerm,"#$qaIrrelevantTerm is a unary predicate. (#$qaIrrelevantTerm TERM) means that TERM should be more or less ignored from the Query Augmentation application.  More precisely, printed representations of TERM (for example via #$preferredGenUnit) should not show up in the Query Augmentation (QA) Interface.  On the other hand, (#$qaIrrelevantTerm TERM) should not entail that QA relevant deductions will be ignored.  For example, #$WebSearchRuleMacroPredicate is not something which QA users will want to search on, thus (#$qaIrrelevantTerm #$WebSearchRuleMacroPredicate) should be asserted.  Such an assertion does not preclude this term from being mentioned in rules which conclude #$qaFollowupConcepts.") :- x_cid(a65b1280033733).
xc_microtheory(a65b1280033733,x_WebSearchEnhancementMt).
xc_source_file(a65b1280033733,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/WebSearchEnhancementMt.krf').
