xc_mapping_rows(a65b1280033734,[]).
x_comment(x_omitFromFollowUps,"(#$omitFromFollowUps CONC) means that CONC is a concept that should not be offered as a follow-up for a query in the context of our query augmentation application. A good example of an ARG1 for such an assertion would be #$Device-UserPowered. Although this constant is a legitimate node in Cyc's ontology -- it allows for generalizations that are extremely useful from the point of view of Knowledge Representation -- it is at the same time too general a concept to be of much use in a web search.  Note that this does not affect the disambiguation phase of query augmentation.  Nor does it affect subtopic followups.  Rather it only affects presentation of related follow up concepts (see #$qaConceptPrintString for more details on what related follow up concepts are, and how to generate them.)") :- x_cid(a65b1280033735).
xc_microtheory(a65b1280033735,x_WebSearchEnhancementMt).
xc_source_file(a65b1280033735,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/WebSearchEnhancementMt.krf').
xc_source_line(a65b1280033735,534).
xc_kb_names(a65b1280033735,[]).
xc_mapping_rows(a65b1280033735,[]).
x_comment(x_ScriptOfCWFn,"#$ScriptOfCWFn takes as argument a specific #$ConceptualWork with spoken words (e.g. TV series, radio series, or movie) and returns the collection of those #$WordsToPCW containing scripts of that specific #$ConceptualWork. For example, (#$ScriptOfCWFn EPISODE), where EPISODE is a specific episode of #$StarTrek-Classic, returns the words to that episode. This function differs from #$TranscriptOfCWFn in that #$ScriptOfCWFn is intended to be used for scripted events (e.g. those in which a script is written ahead of time), while #$TranscriptOfCWFn is intended for un-scripted events, of which a transcript is only made after the fact.") :- x_cid(a65b1280033736).
xc_microtheory(a65b1280033736,x_WebSearchEnhancementMt).
xc_source_file(a65b1280033736,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/WebSearchEnhancementMt.krf').
xc_source_line(a65b1280033736,535).
