xc_mapping_rows(a65b1280033736,[]).
x_comment(x_webConceptuallyRelated,"(#$webConceptuallyRelated ?ARG1 ?ARG2) means that ?ARG1 and ?ARG2 should be considered related concepts for the purpose of the Query Augmentation application.  If a web search user is asking about concept ?ARG1, then it's reasonable to ask them if they want information about ?ARG2.  #$webConceptuallyRelated is more general than #$conceptuallyRelated, lacking both the inheritance to specs and instances that #$conceptuallyRelated exhibits, and the constraint that conceptuallyRelated not hold between concepts that are in genls or isa relationships.") :- x_cid(a65b1280033737).
xc_microtheory(a65b1280033737,x_WebSearchEnhancementMt).
xc_source_file(a65b1280033737,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/WebSearchEnhancementMt.krf').
