x_comment('x_Sweepstakes-Event',"A #$Sweepstakes-Event has specs whose #$subEvents include a #$Drawing-RandomSelection; however, not all #$Events which have a #$Drawing-RandomSelection are #$specs of #$Sweepstakes-Event. For example, #$Lottery is not a spec of #$Sweepstakes-Event, but #$PublishersClearingHouse-SweepstakesEvent is. A #$Sweepstakes-Event does not require a purchase or a bet.") :- x_cid(a65b128003373a).
