x_comment(x_qaValidationForts,"(#$qaValidationForts FORT1 FORT2) means that FORT2 is a concept that validates the proper name FORT3 interpretation of a substring STRING in a query submitted to the #$QueryAugmentationApplication whenever FORT3 is a known instance of FORT1. Validation is only required if STRING is ambiguous with respect to the #$QueryAugmentationApplication. For example  (#$qaValidationForts #$Movie-CW #$Actor) validates the #$Big-TheMovie interpretation of the string `big' in the query `big actor', under the assumption that the substring `actor' maps on the constant #$Actor. #$qaValidationForts assertions are assumed to   represent complete knowledge about what validates a proper name interpretation of a #$QueryAugmentationApplication query substring. The intended effect is to disallow the #$Big-TheMovie interpretation of the string `big' in a query such as `big boats' where no other substring in the query maps to any validating FORTs for any of the collections of which #$Big-TheMovie is a member.") :- x_cid(a65b128003373b).
xc_microtheory(a65b128003373b,x_WebSearchEnhancementMt).
